"""The build constraints writer: what the standalone build installs against."""

from __future__ import annotations

from pathlib import Path

from tools.build import make_constraints

_LOCK = """\
#
# This file is autogenerated by pip-compile with Python 3.12
# by the following command:
#
#    bazel run //:requirements_test.update
#
annotated-types==0.8.0 \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
    # via pydantic
PySide6_Essentials==6.12.0 \\
    --hash=sha256:cccc
    # via teachers-teammate (pyproject.toml)

smart-open[http]==9.0.2 \\
    --hash=sha256:eeee
    # via spacy

# The following packages are considered to be unsafe in a requirements file:
setuptools==84.2.1 \\
    --hash=sha256:dddd
"""


def test_parse_pins_keeps_names_and_versions_only() -> None:
    """Given a lock with hashes and comments, When the pins are parsed, Then only name==version remains."""
    assert make_constraints.parse_pins(_LOCK) == [
        "annotated-types==0.8.0",
        "PySide6_Essentials==6.12.0",
        "smart-open==9.0.2",
        "setuptools==84.2.1",
    ]


def test_merge_normalizes_names_and_lets_the_platform_file_win() -> None:
    """Given a lock and a platform file naming the same package, When they are merged, Then the platform pin wins."""
    merged = make_constraints.merge(
        ["PySide6_Essentials==6.12.0", "pyinstaller==6.0"],
        ["pyinstaller==6.22.3", "pywin32-ctypes==0.2.3"],
    )

    assert merged == {
        "pyside6-essentials": "6.12.0",
        "pyinstaller": "6.22.3",
        "pywin32-ctypes": "0.2.3",
    }


def test_main_writes_sorted_pins(tmp_path: Path, monkeypatch) -> None:
    """Given a lock and a platform file, When the constraints are written, Then the file is sorted and complete."""
    lock = tmp_path / "lock.txt"
    lock.write_text(_LOCK, encoding="utf-8")
    platform = tmp_path / "platform.txt"
    platform.write_text("# a comment\npyinstaller==6.22.3\n", encoding="utf-8")
    output = tmp_path / "out" / "constraints.txt"
    monkeypatch.setattr(make_constraints, "LOCK", lock)
    monkeypatch.setattr(make_constraints, "PLATFORM", platform)
    monkeypatch.setattr(make_constraints, "OUTPUT", output)

    assert make_constraints.main() == 0

    assert output.read_text(encoding="utf-8").splitlines() == [
        "annotated-types==0.8.0",
        "pyinstaller==6.22.3",
        "pyside6-essentials==6.12.0",
        "setuptools==84.2.1",
        "smart-open==9.0.2",
    ]


def test_the_committed_platform_file_pins_the_build_tools() -> None:
    """Given the committed platform file, When it is parsed, Then PyInstaller and its Windows dependency are pinned."""
    pins = make_constraints.parse_pins(make_constraints.PLATFORM.read_text(encoding="utf-8"))

    names = {pin.partition("==")[0].lower() for pin in pins}
    assert {"pyinstaller", "pyinstaller-hooks-contrib", "pywin32-ctypes"} <= names
    assert all("==" in pin for pin in pins)
